+  assert.equal(wordCount('١٢٣'), 1);
+  assert.equal(wordCount('١٢٣ ٤٥'), 2);
+});
+
+test('returns 0 for a string made only of punctuation and joiners', () => {
+  assert.equal(wordCount("...!?—–-'’_/ ,;:"), 0);
+});
